// Prepare all data needed for the entire pipeline

const runFolder = $('When Executed by Another Workflow').first().json.path;
const runId = $('When Executed by Another Workflow').first().json.run_id;
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const xmlData = $input.first().json;
const workflowTypeIsXp = $('When Executed by Another Workflow').first().json.is_xp || false;

// Define paths
const outputBase = '/staging/tmp';
const outputDir = `${outputBase}/${runId}-Fastq`;
const logFile = `bcl_convert_${timestamp}.log`;
const logPath = `${outputDir}/${logFile}`;
const fullRunPath = `/staging/tmp/${runId}`;
const scriptDir = '/staging/n8n_tmp';

// BCL-Convert command
const bclConvertCommand = `mkdir -p "${outputDir}" && dragen -f --bcl-conversion-only true --bcl-sampleproject-subdirectories true --bcl-input-directory "${fullRunPath}" --no-lane-splitting ${!workflowTypeIsXp} --output-directory "${outputDir}" --first-tile-only false --bcl-only-matched-reads true 2>&1 | tee "${logPath}"`;

// Webhook URLs
const webhookBase = 'http://10.20.0.30:5678/webhook';

return [{
  json: {
    // Original inputs
    path: runFolder,
    run_id: runId,
    is_xp: workflowTypeIsXp,

    // Parsed XML data
    xmlData: xmlData,

    // Computed paths
    outputDirectory: outputDir,
    logFile: logFile,
    logPath: logPath,
    fullRunPath: fullRunPath,
    scriptDir: scriptDir,

    // Commands
    bclConvertCommand: bclConvertCommand,

    // Metadata
    startTime: new Date().toISOString(),
    executionId: `${runId}_${timestamp}`,
    workflowType: workflowTypeIsXp ? 'XP' : 'Standard',
    noLaneSplitting: !workflowTypeIsXp,

    // Webhook URLs for callbacks
    webhooks: {
      postStaging: `${webhookBase}/post-staging`,
      postBclConvert: `${webhookBase}/post-bclconvert`,
      postCopy: `${webhookBase}/post-copy`,
      errorHandler: `${webhookBase}/bcl-error`
    }
  }
}];

// Generate the staging script content
const data = $('Prepare Pipeline Data').first().json;

// Get the source path from the other node
const sourcePath = $('When Executed by Another Workflow').first().json.path;

// Store payload as base64 to avoid all quoting issues
const payloadJson = JSON.stringify(data);
const payloadBase64 = Buffer.from(payloadJson).toString('base64');

const scriptContent = `#!/bin/bash
# Stage 1: Copy run folder to staging
# Run ID: ${data.run_id}
# Generated: ${data.startTime}
set -o pipefail
RUN_ID="${data.run_id}"
SOURCE_PATH="${sourcePath}"
DEST_PATH="/staging/tmp/${data.run_id}"
LOG_FILE="${data.scriptDir}/${data.run_id}_stage1_staging.log"
WEBHOOK_SUCCESS="${data.webhooks.postStaging}"
WEBHOOK_ERROR="${data.webhooks.errorHandler}"

# Payload stored as base64 to avoid quoting issues
PAYLOAD_BASE64="${payloadBase64}"

# Decode payload
PAYLOAD_BASE=$(echo "$PAYLOAD_BASE64" | base64 -d)

echo "=== Staging Script Started at $(date) ===" | tee "$LOG_FILE"
echo "Source: $SOURCE_PATH" | tee -a "$LOG_FILE"
echo "Destination: $DEST_PATH" | tee -a "$LOG_FILE"

# Run rsync
rsync -avh "$SOURCE_PATH/" "$DEST_PATH/" 2>&1 | tee -a "$LOG_FILE"
EXIT_CODE=$?

echo "" | tee -a "$LOG_FILE"
echo "=== Staging Script Finished at $(date) with exit code $EXIT_CODE ===" | tee -a "$LOG_FILE"

# Prepare callback payload
if [ $EXIT_CODE -eq 0 ]; then
  echo "Calling success webhook..." | tee -a "$LOG_FILE"
  curl -s -X POST "$WEBHOOK_SUCCESS" \\
    -H "Content-Type: application/json" \\
    -d "$PAYLOAD_BASE" | tee -a "$LOG_FILE"
else
  echo "Calling error webhook..." | tee -a "$LOG_FILE"
  ERROR_PAYLOAD=$(echo "$PAYLOAD_BASE" | jq --arg ec "$EXIT_CODE" --arg stage "staging" '. + {error_stage: $stage, exit_code: ($ec|tonumber), error_message: "rsync to staging failed"}')
  curl -s -X POST "$WEBHOOK_ERROR" \\
    -H "Content-Type: application/json" \\
    -d "$ERROR_PAYLOAD" | tee -a "$LOG_FILE"
fi

echo "" | tee -a "$LOG_FILE"
echo "Webhook called, script complete." | tee -a "$LOG_FILE"
`;

// Also encode the entire script as base64 for safe transfer
const scriptBase64 = Buffer.from(scriptContent).toString('base64');

return [{
  json: {
    ...data,
    stagingScript: scriptContent,
    stagingScriptBase64: scriptBase64,
    stagingScriptPath: `${data.scriptDir}/${data.run_id}_stage1_staging.sh`
  }
}];

// Return confirmation that staging job was launched
const data = $('Generate Staging Script').first().json;

return [{
  json: {
    status: 'staging_launched',
    run_id: data.run_id,
    tmux_session: `bcl_${data.run_id}_staging`,
    script_path: data.stagingScriptPath,
    message: 'Staging rsync launched in tmux. Webhook will be called on completion.',
    launched_at: new Date().toISOString()
  }
}];

